SELECT id, alarm_id, classroom_id, device_id, alarm_type, level, detail,
       action_taken, status, handled_by, handled_at, created_at
FROM alarms


        AND created_at >= #{from}


        AND created_at <= #{to}


        AND status = #{status}


ORDER BY created_at DESC, id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM alarms


        AND created_at >= #{from}


        AND created_at <= #{to}


        AND status = #{status}
